'use strict';
const G=CloudGame,$=id=>document.getElementById(id);
let state=G.fresh(),storageOK=true,migrated=0;state.phase='workshop';
try{const raw=localStorage.getItem(G.KEY);if(raw){migrated=JSON.parse(raw).version<15?JSON.parse(raw).version:0;if(migrated){try{if(!localStorage.getItem(G.KEY+"-before-celsius-v15"))localStorage.setItem(G.KEY+"-before-celsius-v15",raw);}catch{}}state=G.load(raw);}}catch{storageOK=false;}
let currentScreen=state.phase==='active'?'play':state.lastRound?'results':'workbench';try{const selected=sessionStorage.getItem('cloud-chaser-screen');if(['play','results','workbench'].includes(selected))currentScreen=selected;}catch{}
let tab='liquid',activeInput=null,lastTime=performance.now(),lastPhase=state.phase,lastPuffCount=state.round.puffs,lastAction=state.action,toastTimer,renderTime=0;
const fmt=(n,d=1)=>{for(const [v,s]of [[1e12,'T'],[1e9,'B'],[1e6,'M'],[1e3,'K']])if(n>=v)return(n/v).toFixed(d)+s;return n.toLocaleString('en-GB',{maximumFractionDigits:d,minimumFractionDigits:d});};
function toast(message){$('toast').textContent=message;$('toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('visible'),4000);}
function save(){state.savedAt=Date.now();try{localStorage.setItem(G.KEY,JSON.stringify(state));storageOK=true;$('save-status').textContent='● Progress saved locally';}catch{storageOK=false;$('save-status').textContent='Save unavailable — export in settings';}$('save-note').textContent=storageOK?'Autosaves every 5s.':'Use Export save in settings.';}
const screenCopy={play:['Play','Find your rhythm. Keep your cloud clean.'],results:['Results','Your payout. The details only when you need them.'],workbench:['Workbench','Build your setup. Tune your next session.']};
function rememberScreen(){try{sessionStorage.setItem('cloud-chaser-screen',currentScreen);}catch{}}
function applyScreen(){for(const name of Object.keys(screenCopy))$('screen-'+name).hidden=currentScreen!==name;document.querySelectorAll('[data-screen]').forEach(b=>{if(b.id.startsWith('nav-')){if(b.dataset.screen===currentScreen)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current');}});$('screen-title').textContent=screenCopy[currentScreen][0];$('screen-subtitle').textContent=screenCopy[currentScreen][1];document.body.dataset.screen=currentScreen;}
function scrollToScreen(){requestAnimationFrame(()=>$('screen-heading').scrollIntoView({behavior:state.reduced||matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'start'}));}
function selectScreen(name){if(!screenCopy[name]||name===currentScreen)return;interrupt();currentScreen=name;rememberScreen();lastTime=performance.now();render();scrollToScreen();}
function effect(k,st){const next=G.stats({...state,levels:{...state.levels,[k]:state.levels[k]+1}});switch(k){case'wattage':return`${fmt(st.watts,1)} → ${fmt(next.watts,1)} W electronics ceiling`;case'airflow':return`${fmt(st.drawCooling)} → ${fmt(next.drawCooling)} ${st.isC?'°C':'heat'} removed / draw sec`;case'coil':return`${st.ohms.toFixed(2)} → ${next.ohms.toFixed(2)} Ω · ${fmt(st.surface)}× → ${fmt(next.surface)}× area · mass ${fmt(st.thermalMass,2)} → ${fmt(next.thermalMass,2)}×`;case'wicking':return`${fmt(st.wickRate)} → ${fmt(next.wickRate)} mL/s absorption · ${fmt(st.wickCapacity,2)} → ${fmt(next.wickCapacity,2)} mL wick`;case'viscosity':return`${fmt(st.wickRate)} → ${fmt(next.wickRate)} mL/s absorption`;case'cooling':return`${fmt(st.activeCooling)} → ${fmt(next.activeCooling)} extra ${st.isC?'°C':'heat'} removed / transfer sec`;case'retention':return`${fmt(st.cooling)} → ${fmt(next.cooling)} heat lost / resting sec · slower recovery`;case'battery':return`${fmt(st.capacity,4)} → ${fmt(next.capacity,4)} Wh internal storage`;case'pack':return`${fmt(st.packCapacity,4)} → ${fmt(next.packCapacity,4)} Wh external reserve`;case'supply':return`${fmt(st.stockCapacity)} → ${fmt(next.stockCapacity)} mL session reserve`;case'tank':return`${fmt(st.tank,0)} → ${fmt(next.tank,0)} mL tank capacity`;case'density':return`${fmt(st.density,2)}× → ${fmt(next.density,2)}× clouds · +10% liquid use`;case'economy':return`${fmt(st.liquidRate,2)} → ${fmt(next.liquidRate,2)} mL liquid / sec`;case'thermal':return`${fmt(st.optimalLow,Number.isInteger(st.optimalLow)?0:1)}–${fmt(st.optimalHigh,Number.isInteger(st.optimalHigh)?0:1)} → ${fmt(next.optimalLow,Number.isInteger(next.optimalLow)?0:1)}–${fmt(next.optimalHigh,Number.isInteger(next.optimalHigh)?0:1)} ${st.isC?'°C optimal':'% (legacy)'}`;case'draw':return`${fmt(st.drawStrength,2)}× → ${fmt(next.drawStrength,2)}× draw · ${fmt(st.lungUsage,2)} → ${fmt(next.lungUsage,2)} lung units / sec`;case'lungs':return`${fmt(st.lungCapacity)} → ${fmt(next.lungCapacity)} capacity units`;case'recovery':return`${fmt(st.lungRecovery)} → ${fmt(next.lungRecovery)} units / resting sec`;}}
function renderCards(){renderDevices();document.querySelectorAll('[data-tab]').forEach(b=>{const unlocked=G.groupUnlocked(state,b.dataset.tab);b.classList.toggle('feature-locked',!unlocked);b.setAttribute('aria-selected',b.dataset.tab===tab);b.querySelector('span').textContent=unlocked?String(G.upgradeGroups[b.dataset.tab].keys.length).padStart(2,'0'):'LOCKED';});const st=G.stats(state),list=$('upgrade-list');list.replaceChildren();const component=G.upgradeGroups[tab],group=G.refundGroup(state,tab),hasShared=component.keys.some(k=>G.upgrades[k].category),hasHardware=component.keys.some(k=>!G.upgrades[k].category);$('component-description').textContent=(!G.groupUnlocked(state,tab)?`Unlock with ${G.unlockDevice(tab).name}. Existing investments remain effective and refundable. `:'')+component.description+(tab==='tricks'?'':hasShared?' Shared upgrades affect all devices.':' Hardware upgrades belong to this device.');$('refund-tools').innerHTML=tab==='tricks'?'':`<button class="secondary" id="refund-group" ${state.phase!=='workshop'||group.cost<=0?'disabled':''}>Refund ${component.name+' upgrades'+(hasShared?(hasHardware?' · device + shared':' · all devices'):' · this device')} · ${fmt(group.cost)} Credits${group.estimated?' · estimated':''}</button>${hasHardware?`<button class="secondary" id="refund-device" ${state.phase!=='workshop'||G.refundGroup(state,'hardware').cost<=0?'disabled':''}>Refund all hardware on this device · ${fmt(G.refundGroup(state,'hardware').cost)} Credits${G.refundGroup(state,'hardware').estimated?' · estimated':''}</button>`:''}`;if(tab==='tricks'){for(const t of G.tricks){const row=document.createElement('div');row.className='upgrade';row.innerHTML=`<div class="upgrade-icon">${t.icon}</div><div><h3>${t.name}</h3><p>${t.description}</p><div class="effect">+${Math.round(t.bonus*100)}% output · ${fmt(t.at,0)} scored vapor</div></div><span class="tag">${state.run>=t.at?'UNLOCKED':'MILESTONE'}</span>`;list.append(row);}return;}
 for(const [k,u]of component.keys.map(k=>[k,G.upgrades[k]])){const level=state.levels[k],max=level>=G.levelLimit(state,k),row=document.createElement('div');row.className='upgrade';const name=u.names?u.names[Math.min(6,Math.floor((level-1)/4))]:'';row.innerHTML=`<div class="upgrade-icon">${u.icon}</div><div><h3>${u.name}<span>LV ${String(level).padStart(2,'0')} / ${G.levelLimit(state,k)}</span></h3><p>${name?name+' · ':''}${u.description}</p><small class="upgrade-scope">${u.category?'Shared · all devices':'Hardware · this device'}</small><div class="effect">${max?(u.category?'Fully upgraded.': 'Device ceiling reached. Explore your next rig.'):effect(k,st)}</div></div><div class="upgrade-level-controls"><div class="upgrade-stepper"><button class="refund-level" data-refund="${k}" aria-label="Refund one level of ${u.name}">−</button><span class="upgrade-level-value" aria-label="Current level ${level}">Lv ${level}</span><button class="buy" data-buy="${k}" aria-label="Upgrade ${u.name}">+</button></div><small class="upgrade-buy-cost"></small><small class="upgrade-refund-cost"></small></div>`;list.append(row);updateBuy(row.querySelector('[data-buy]'),k);const q=G.refundQuote(state,k),refund=row.querySelector('[data-refund]');refund.disabled=state.phase!=='workshop'||level<=G.baseline(state,k);refund.title=state.phase!=='workshop'?'Adjust upgrades between sessions':level<=G.baseline(state,k)?'Starting level — cannot reduce further':`Refund one level · ${fmt(q.cost)} Credits${q.estimated?' · estimated':''}`;row.querySelector('.upgrade-refund-cost').textContent=level<=G.baseline(state,k)?'− Starting level':`− Refund ${fmt(q.cost)} Credits${q.estimated?' (estimated)':''}`;}}
function updateBuy(b,k){const u=G.upgrades[k],max=state.levels[k]>=G.levelLimit(state,k),locked=!G.upgradeUnlocked(state,k)||state.total<(u.unlock||0),price=G.cost(state,k);b.disabled=state.phase!=='workshop'||max||locked||state.vapor<price;b.textContent='+';const label=max?'At ceiling':locked?'Rig unlock required':`${fmt(price,0)} Credits`;b.title=state.phase!=='workshop'?'Adjust upgrades between sessions':max?'Maximum level reached':locked?'Unlock this component with a new rig':`Buy one level · ${label}`;b.closest('.upgrade-level-controls').querySelector('.upgrade-buy-cost').textContent=max||locked?label:`+ Buy ${label}`;}
function renderDevices(){const list=$('device-list');list.replaceChildren();for(const [i,d]of G.devices.entries()){const owned=!!state.owned[d.id],selected=state.device===d.id,available=i===0||!!state.owned[G.devices[i-1].id];if(!owned&&!available)continue;const card=document.createElement('article');card.className='device-card'+(selected?' selected':'');card.innerHTML=`<span class="eyebrow">${d.tag}</span><h3>${d.name}</h3><p>${d.description}</p><p class="effect">${owned?'Owned build':'Starts at hardware level '+d.floor} · base hardware ceiling ${d.cap}${d.area>1?' · '+fmt(d.area,2)+'× heating area':''}</p><p class="device-start">${fmt(10*1.42**(d.floor-1))} W starting ceiling · ${fmt(.015*1.48**(d.floor-1),4)} Wh internal · ${fmt(12*1.48**(d.floor-1),0)} mL tank</p><button class="${selected?'secondary':'primary'}" data-device="${d.id}">${selected?'✓ Equipped':owned?'Equip this device':`Buy & equip · ${d.price.toLocaleString('en-GB')} Credits`}</button>${!owned?'<small>Starts above an evenly upgraded level '+d.floor+' rig. Full session supplies at start.</small>':''}`;const b=card.querySelector('button');b.disabled=selected||state.phase!=='workshop'||(!owned&&state.vapor<d.price);list.append(card);}}
