let gaugeKey='';function renderGauge(st){$('optimal-range').textContent=`Optimal ${fmt(st.optimalLow,Number.isInteger(st.optimalLow)?0:1)}–${fmt(st.optimalHigh,Number.isInteger(st.optimalHigh)?0:1)}${st.isC?'°C':'% · legacy'} · smoke above ${st.hot}${st.isC?'°C':'%'}`;$('heat-gauge').setAttribute('aria-valuemin',st.heatMin);$('heat-gauge').setAttribute('aria-valuemax',st.heatMax);const key=[st.heatMin,st.heatMax,st.optimalLow,st.optimalHigh].join(':');if(key===gaugeKey)return;gaugeKey=key;const angle=v=>Math.PI*(1-(v-st.heatMin)/(st.heatMax-st.heatMin)),point=(v,r=104)=>[130+r*Math.cos(angle(v)),135-r*Math.sin(angle(v))],values=[st.heatMin,st.optimalLow,st.optimalHigh,st.hot,st.heatMax],paths=document.querySelectorAll('#heat-gauge svg>g:first-child path');paths.forEach((path,i)=>{const a=point(values[i]),b=point(values[i+1]);path.setAttribute('d',`M ${a[0]},${a[1]} A 104 104 0 0 1 ${b[0]},${b[1]}`);});document.querySelectorAll('#heat-gauge .gauge-ticks text').forEach((text,i)=>{const p=point(values[i],118);text.textContent=fmt(values[i],Number.isInteger(values[i])?0:1);text.setAttribute('x',p[0]);text.setAttribute('y',p[1]);text.setAttribute('text-anchor','middle');});}
function renderPerformance(id,r){const p=G.E.performance(r),bonus=r.earnings?G.E.report(r.earnings,r).throughputBonus:G.E.calculate(r).throughputBonus;$(id).innerHTML=[['Active session time',p.session,'s'],['Firing time',p.firing,'s'],['Average clean throughput',p.throughput,'L/s'],['Average liquid consumption',p.liquidRate,'mL/s'],['Average firing power',p.averagePower,'W'],['Throughput bonus',r.throughputModel?bonus:null,'×']].map(([label,value,unit])=>`<div><span>${label}</span><strong>${value===null?'Not recorded':fmt(value,unit==='L/s'?5:2)+' '+unit}</strong></div>`).join('');}
function advance(now=performance.now()){if(now<lastTime)return;const dt=(now-lastTime)/1000;lastTime=now;if(!document.hidden&&currentScreen==='play')G.tick(state,dt);}
function begin(kind,input){if(currentScreen!=='play')return false;advance();if(activeInput)return false;const ok=kind==='draw'?G.beginDraw(state):kind==='charge'?G.beginRecharge(state):G.beginRefill(state);if(ok)activeInput={kind,...input};else if(kind==='refill'&&state.stock<=1e-8)toast('Session liquid reserve is empty.');render();return ok;}
function release(minimum=true){advance();if(activeInput){if(activeInput.kind==='draw')G.endDraw(state,'released',minimum);else if(activeInput.kind==='charge')G.endRecharge(state);else G.endRefill(state);}activeInput=null;render();save();}
function interrupt(){advance();G.pause(state);activeInput=null;render();save();}
for(const [id,kind]of [['puff','draw'],['refill-button','refill'],['recharge-button','charge']]){const b=$(id);b.addEventListener('pointerdown',e=>{if(e.button!==0)return;e.preventDefault();if(begin(kind,{pointer:e.pointerId,startY:e.clientY}))b.setPointerCapture(e.pointerId);});b.addEventListener('pointerup',e=>{if(activeInput?.pointer===e.pointerId)release();});for(const n of ['pointercancel','lostpointercapture'])b.addEventListener(n,e=>{if(activeInput?.pointer===e.pointerId)interrupt();});b.addEventListener('click',e=>{if(e.detail===0&&!activeInput&&begin(kind,{assistive:true}))release();});b.addEventListener('contextmenu',e=>e.preventDefault());}
window.addEventListener('pointerup',e=>{if(activeInput?.pointer===e.pointerId)release();});window.addEventListener('pointercancel',e=>{if(activeInput?.pointer===e.pointerId)interrupt();});
