$('device-list').onclick=e=>{const b=e.target.closest('[data-device]');if(!b)return;const id=b.dataset.device,owned=!!state.owned[id];if(owned?G.selectDevice(state,id):G.buyDevice(state,id)){renderCards();render();save();toast(G.device(state).name+(owned?' equipped.':' purchased and equipped. No progress reset.'));}};
document.addEventListener('keydown',e=>{if(currentScreen!=='play'||e.ctrlKey||e.metaKey||e.altKey||document.querySelector('dialog[open]'))return;if(e.repeat){if(activeInput?.key===e.code)e.preventDefault();return;}if(/INPUT|TEXTAREA|SELECT/.test(e.target.tagName))return;let kind;if(e.code==='Space'&&(e.target.tagName!=='BUTTON'||e.target.id==='puff'))kind='draw';if(e.code==='KeyR')kind='refill';if(e.code==='KeyC')kind='charge';if(['Space','Enter'].includes(e.code)&&e.target.id==='recharge-button')kind='charge';if(['Space','Enter'].includes(e.code)&&e.target.id==='refill-button')kind='refill';if(e.code==='Enter'&&e.target.id==='puff')kind='draw';if(kind){e.preventDefault();begin(kind,{key:e.code});}});document.addEventListener('keyup',e=>{if(activeInput?.key===e.code){e.preventDefault();release();}});window.addEventListener('blur',interrupt);document.addEventListener('visibilitychange',()=>{lastTime=performance.now();G.pause(state);activeInput=null;render();save();});window.addEventListener('pagehide',interrupt);
