function frame(now){advance(now);if(currentScreen==='play'){const min=state.temperatureScale==='C'?20:0,max=state.temperatureScale==='C'?320:100;$('heat-needle').style.transform=`rotate(${(state.heat-min)/(max-min)*180}deg)`;}if(now-renderTime>50||lastPhase!==state.phase||lastPuffCount!==state.round.puffs){render();renderTime=now;}requestAnimationFrame(frame);}ProgressUI.init();CloudographUI.init();setInterval(()=>{if(!document.hidden)save();},5000);renderCards();render();save();requestAnimationFrame(frame);if(migrated)setTimeout(()=>toast('Celsius update: active sessions retain their original percentage model; new sessions use °C. Thermal Stability now widens the optimal window.'),500);if(!storageOK)toast('Storage unavailable. Export your save from Settings.');

